/**
 * AUTO-DISCOVERY — Scenes are loaded automatically from this directory.
 *
 * Convention:
 *   - File name: NNN_SceneName.tsx  (e.g., 001_Intro.tsx, 002_Problem.tsx)
 *   - Files starting with _ are ignored (e.g., _Template.tsx)
 *   - Each file must export:
 *       export const config: SceneConfig = { id, title, durationInSeconds };
 *       const MyScene: React.FC = () => { ... };
 *       export default MyScene;
 *
 * DO NOT EDIT THIS FILE when adding scenes. Just create a new NNN_Name.tsx file.
 */

import React from "react";

export type { SceneConfig } from "./types";

export interface SceneEntry {
  /** Sort order derived from filename prefix (e.g., 1, 2, 3) */
  order: number;
  /** The scene's exported config */
  config: import("./types").SceneConfig;
  /** The scene's React component */
  Component: React.FC;
}

// Webpack require.context: scans this directory for matching .tsx files at build time.
// Excludes files starting with _ (templates/helpers).
const sceneContext = (require as any).context(
  ".",
  false,
  /^\.\/\d{3}_[A-Za-z0-9_]+\.tsx$/
);

const discovered: SceneEntry[] = sceneContext
  .keys()
  .map((key: string) => {
    const mod = sceneContext(key);
    const match = key.match(/^\.\/(\d{3})_/);
    if (!match) return null;

    const order = parseInt(match[1], 10);

    if (!mod.config) {
      console.warn(`Scene file ${key} is missing 'export const config'. Skipping.`);
      return null;
    }
    if (!mod.default) {
      console.warn(`Scene file ${key} is missing a default export. Skipping.`);
      return null;
    }

    return {
      order,
      config: mod.config as import("./types").SceneConfig,
      Component: mod.default as React.FC,
    };
  })
  .filter((entry: SceneEntry | null): entry is SceneEntry => entry !== null)
  .sort((a: SceneEntry, b: SceneEntry) => a.order - b.order);

// Warn on duplicate IDs
const ids = new Set<string>();
for (const scene of discovered) {
  if (ids.has(scene.config.id)) {
    console.error(
      `Duplicate scene ID: "${scene.config.id}". Each scene must have a unique id.`
    );
  }
  ids.add(scene.config.id);
}

export const scenes: SceneEntry[] = discovered;
